                                                                                                                                                                                                                
  CREATE TABLE "JW_WORKBENCH_TEMPLATE"                                                                                                                                                           
   (	"TEMPLATE_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 23 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"TENANT_ID" NUMBER(20,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                            
	"CREATED_BY" NVARCHAR2(256),                                                                                                                                                                                   
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                          
	"UPDATED_BY" NVARCHAR2(256),                                                                                                                                                                                   
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                            
	"TEMPLATE_PREVIEW" VARCHAR2(255),                                                                                                                                                                              
	"TEMPLATE_NAME" VARCHAR2(64) NOT NULL ENABLE,                                                                                                                                                                  
	"TEMPLATE_TYPE" VARCHAR2(32) DEFAULT 'SUB_LINK',                                                                                                                                                               
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                             
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                              
	"TEMPLATE_URL" VARCHAR2(255) NOT NULL ENABLE,                                                                                                                                                                  
	"SCOPE_TYPE" VARCHAR2(15) DEFAULT 'ALL' NOT NULL ENABLE,                                                                                                                                                       
	 PRIMARY KEY ("TEMPLATE_ID")                                                                                                                                                                                   
  USING INDEX  ENABLE                                                                                                                                                                                           
   ) ;                                                                                                                                                                                                          

